import React, { useState } from 'react';
import './StaffAdminLoginPage.css';

const StaffAdminLoginPage = () => {
  const [activeTab, setActiveTab] = useState('account');
  const [loginData, setLoginData] = useState({
    username: '',
    password: ''
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setLoginData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Staff/Admin login:', loginData);
  };

  return (
    <div className="staff-admin-login-page">
      <div className="staff-admin-login-container">
        <div className="logo-section">
          <img src="/LEAF.png" alt="LEAF" className="logo" />
        </div>
        
        <div className="login-content">
          <h1 className="login-title">Đăng nhập</h1>
          
          {/* Tab Navigation */}
          <div className="tab-navigation">
            <button 
              className={`tab-button ${activeTab === 'account' ? 'active' : ''}`}
              onClick={() => setActiveTab('account')}
            >
              Tài khoản
            </button>
            <button 
              className={`tab-button ${activeTab === 'password' ? 'active' : ''}`}
              onClick={() => setActiveTab('password')}
            >
              Mật khẩu
            </button>
          </div>

          {/* Login Form */}
          <form onSubmit={handleSubmit} className="staff-admin-login-form">
            {activeTab === 'account' && (
              <div className="form-section">
                <input
                  type="text"
                  name="username"
                  placeholder="Tên đăng nhập hoặc Email"
                  value={loginData.username}
                  onChange={handleInputChange}
                  className="login-input"
                  required
                />
              </div>
            )}
            
            {activeTab === 'password' && (
              <div className="form-section">
                <input
                  type="password"
                  name="password"
                  placeholder="Mật khẩu"
                  value={loginData.password}
                  onChange={handleInputChange}
                  className="login-input"
                  required
                />
              </div>
            )}
            
            <button type="submit" className="login-button">
              Đăng Nhập
            </button>
          </form>

          {/* Additional Options */}
          <div className="login-options">
            <div className="remember-forgot">
              <label className="remember-checkbox">
                <input type="checkbox" />
                <span>Ghi nhớ đăng nhập</span>
              </label>
              <button className="forgot-password" onClick={() => console.log('Forgot password')}>
                Quên mật khẩu?
              </button>
            </div>
          </div>

          {/* Role Selection */}
          <div className="role-selection">
            <p className="role-label">Đăng nhập với vai trò:</p>
            <div className="role-options">
              <label className="role-option">
                <input
                  type="radio"
                  name="role"
                  value="staff"
                  defaultChecked
                />
                <span className="role-text">Staff</span>
              </label>
              <label className="role-option">
                <input
                  type="radio"
                  name="role"
                  value="admin"
                />
                <span className="role-text">Admin</span>
              </label>
            </div>
          </div>

          {/* Back to User Login */}
          <div className="back-to-user">
            <button 
              className="back-link" 
              onClick={() => console.log('Navigate back to user login')}
            >
              ← Quay lại đăng nhập người dùng
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StaffAdminLoginPage;
